// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// A function: every x has exactly one y.
// A non-function: at least one x has two or more different y values.

$isFunction = rand(0, 1);

// Generate 4 distinct x-values to use
$xValues = diffrands(0, 10, 4);
// Generate 4 y-values
$yValues = diffrands(0, 10, 4);

if ($isFunction) {
    // Create a set of ordered pairs where each x is unique
    $pairs = [];
    for ($i = 0; $i < 4; $i++) {
        $pairs[] = "(" . $xValues[$i] . ", " . $yValues[$i] . ")";
    }
    $answer = 0; // Index of "Yes, it is a function"
} else {
    // Create a set where one x is repeated with a different y
    $pairs = [];
    // First three are unique
    for ($i = 0; $i < 3; $i++) {
        $pairs[] = "(" . $xValues[$i] . ", " . $yValues[$i] . ")";
    }
    // The fourth pair repeats the first x but uses a different y
    $newY = $yValues[0] + 1; 
    $pairs[] = "(" . $xValues[0] . ", " . $newY . ")";

    $answer = 1; // Index of "No, it is not a function"
}

// To shuffle a single array in IMathAS, we use jointshuffle with a dummy array.
// jointshuffle returns an array containing the two shuffled arrays.
$dummy = fillarray(0, 4, 0);
$shuffledResult = jointshuffle($pairs, $dummy);
$finalPairs = $shuffledResult[0];

$pairString = arraytolist($finalPairs, ", ");

$questions = array(
    "Yes, it is a function",
    "No, it is not a function"
);

if ($isFunction) {
    $solutionguide = 'Each input (x-value) is paired with exactly one output (y-value). Since no x-value is repeated with a different y-value, the relationship is a function.';
} else {
    $repeatedX = $xValues[0];
    $solutionguide = 'The input value ' . $repeatedX . ' is paired with more than one output value. Therefore, the relationship is not a function.';
}

// === QUESTION TEXT ===
Determine if the following relationship is a function. Select the correct answer from the options below.

`{` $pairString `}`

$answerbox

// === ANSWER ===
$solutionguide = $solutionguide;

// === NAME - DESCRIPTION: Addition Rule for Union Probability - Compute P(A or B) and recognize overcounting ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Randomize the two events and their overlap
// P(A) and P(B) should be reasonably large, and P(A and B) must be <= min(P(A), P(B))
$pA = round(rand(30, 60) / 100, 2);
$pB = round(rand(30, 60) / 100, 2);

// The overlap P(A and B) must be at most the smaller of the two
$maxOverlap = min($pA, $pB);
$pAandB = round(rand(10, floor($maxOverlap * 100)) / 100, 2);

// Ensure the union doesn't exceed 1.0
// P(A or B) = P(A) + P(B) - P(A and B)
$pAorB = $pA + $pB - $pAandB;

// If the union > 1, we shift the values down slightly
if ($pAorB > 1.0) {
    $diff = $pAorB - 1.0;
    $pA = round($pA - $diff, 2);
    // Recalculate union to be safe
    $pAorB = $pA + $pB - $pAandB;
}

// Contexts for randomization: noun, phrase A, phrase B, phrase both
$contexts = [
    ["noun" => "student", "A" => "those who like Math", "B" => "those who like Art", "both" => "those who like both"],
    ["noun" => "person", "A" => "those who drink coffee", "B" => "those who drink tea", "both" => "those who drink both"],
    ["noun" => "employee", "A" => "those who work from home", "B" => "those who have a degree", "both" => "those who do both"],
    ["noun" => "car", "A" => "those that are red", "B" => "those that are electric", "both" => "those that are both red and electric"]
];

// randfrom takes one argument: the array to pick from
$ctx = randfrom($contexts);
$noun = $ctx["noun"];
$ctxA = $ctx["A"];
$ctxB = $ctx["B"];
$ctxBoth = $ctx["both"];

// Answers
$answer[0] = round($pAorB, 2);
$answer[1] = 0; // Index for the correct choice regarding overcounting

$questions[1] = [
    "Adding `P(A)` and `P(B)` alone counts the overlap twice, so the result is too high.",
    "Adding `P(A)` and `P(B)` alone ignores the overlap, so the result is too low.",
    "Adding `P(A)` and `P(B)` alone is correct because the events are always mutually exclusive.",
    "The overlap is already subtracted within the individual probabilities `P(A)` and `P(B)`."
];

$anstypes = "number,choices";

// Formatting for display using round
$pADisp = round($pA, 2);
$pBDisp = round($pB, 2);
$pAndDisp = round($pAandB, 2);

// Solution Guide
$solutionguide = "To find the probability of the union (A or B), we use the General Addition Rule: `P(A or B) = P(A) + P(B) - P(A and B)`. 
Substituting the values: `P(A or B) = $pADisp + $pBDisp - $pAndDisp = " . round($pAorB, 2) . "`. 
We subtract the overlap because those individuals are included in both the count for A and the count for B; adding the two probabilities without subtracting the overlap counts those individuals twice.";

// === QUESTION TEXT ===
In a recent survey, it was found that for a randomly selected $noun, the probability that they are among $ctxA is `$pADisp`, the probability that they are among $ctxB is `$pBDisp`, and the probability that they are among $ctxBoth is `$pAndDisp`.

(a) What is the probability that a randomly selected $noun is either among $ctxA OR among $ctxB? 
(Enter your answer as a decimal, such as 0.45)
`P(A or B) =` $answerbox[0]

(b) Why is it necessary to subtract the probability of the overlap `P(A and B)` when calculating the probability of the union?
$answerbox[1]

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$cat_names = array("Red", "Blue", "Green", "Yellow");

// Use a varying total that is a multiple of 10 but not always 100
$totals_pool = array(40, 50, 60, 80, 120, 150, 200);
$total = randfrom($totals_pool);

$counts = array();
$sum = 0;
for ($i = 0; $i < 3; $i++) {
  // Ensure counts are reasonable relative to total
  $val = rand(floor($total * 0.1), floor($total * 0.3));
  $counts[$i] = $val;
  $sum += $val;
}
$counts[3] = $total - $sum;

// Basic check to ensure the 4th category isn't too small or too large
if ($counts[3] < floor($total * 0.1)) {
  // Simple redistribution to keep the graph looking balanced
  $diff = floor($total * 0.1) - $counts[3];
  $counts[3] += $diff;
  $counts[0] -= $diff;
}

// Calculate percentages
$percents = array();
for ($i = 0; $i < 4; $i++) {
  $percents[$i] = ($counts[$i] / $total) * 100;
}

// Pick a random category for part (b)
$target_idx = rand(0, 3);
$target_cat = $cat_names[$target_idx];
$target_pct = $percents[$target_idx];

$anstypes = "number,number,choices";

// Part (a): Total sample size
$answer[0] = $total;

// Part (b): Percentage of the target category
$answer[1] = $target_pct;

// Part (c): Why the shape is the same
// We make distractors clearly wrong (additive or non-linear)
$questions[2] = array(
  "The percentages were calculated by adding a constant value to each count.",
  "The percentages were calculated by dividing each count by the same total sample size.",
  "The percentages were calculated by squaring the counts.",
  "The percentages were calculated by subtracting the smallest count from all others."
);
$answer[2] = 1;

$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

// Build the counts table for the prompt
$table_counts = "<table border='1' style='border-collapse: collapse; text-align: center;'>
  <tr><th style='padding: 5px;'>Category</th><th style='padding: 5px;'>Count</th></tr>";
for ($i = 0; $i < 4; $i++) {
  $table_counts .= "<tr style='text-align: center;'><td style='padding: 5px;'>{$cat_names[$i]}</td><td style='padding: 5px;'>{$counts[$i]}</td></tr>";
}
$table_counts .= "</table>";

$sum_string = arraytolist($counts, ' + ');
$solutionguide = "Part (a): The total sample size is the sum of all counts: " . $sum_string . " = $total.
Part (b): The percentage for $target_cat is ($counts[$target_idx] / $total) * 100 = $target_pct%.
Part (c): The shape of a bar graph depends on the relative heights of the bars. Because every count was divided by the same constant (the total sample size) to get the percentage, the ratios between the bars remain identical, preserving the shape of the graph.";

// === QUESTION TEXT ===
<p>A researcher collected data on the favorite colors of a group of participants. The data is summarized in the table below.</p>

<p><strong>Table 1: Counts</strong><br>$table_counts</p>

<p>(a) What was the total number of participants in the sample? <br>
