$r1 = rand(30, $nTotal - 30);
$r2 = $nTotal - $r1;

// Col 1 total: $c1, Col 2 total: $c2.
$c1 = rand(30, $nTotal - 30);
$c2 = $nTotal - $c1;

// The expected count for a cell is (Row Total * Col Total) / Grand Total.
$e11 = ($r1 * $c1) / $nTotal;
$e12 = ($r1 * $c2) / $nTotal;
$e21 = ($r2 * $c1) / $nTotal;
$e22 = ($r2 * $c2) / $nTotal;

// We will ask for 3 of the 4 cells to avoid redundancy.
$asked = diffrands(0, 3, 4); // Pick 3 indices from 0..3

$ans_vals = array($e11, $e12, $e21, $e22);
$ans_labels = array("Row 1, Column 1", "Row 1, Column 2", "Row 2, Column 1", "Row 2, Column 2");

$anstypes = "number,number,number";

// Map the randomized selection to the answer array
for ($i = 0; $i < 3; $i++) {
    $idx = $asked[$i];
    $answer[$i] = $ans_vals[$idx];
}

// For the question text, we need to know which ones we are asking for.
$q_labels = array();
for ($i = 0; $i < 3; $i++) {
    $q_labels[$i] = $ans_labels[$asked[$i]];
}

// Build solution guide using arraytolist instead of implode
$guide_parts = array();
$row_totals = array("Row 1" => $r1, "Row 2" => $r2);
$col_totals = array("Column 1" => $c1, "Column 2" => $c2);

for ($i = 0; $i < 3; $i++) {
    $idx = $asked[$i];
    $r_name = ($idx == 0 || $idx == 1) ? "Row 1" : "Row 2";
    $c_name = ($idx == 0 || $idx == 2) ? "Column 1" : "Column 2";
    $r_val = $row_totals[$r_name];
    $c_val = $col_totals[$c_name];
    $res = ($r_val * $c_val) / $nTotal;
    $guide_parts[] = "For " . $ans_labels[$idx] . ": (" . $r_val . " * " . $c_val . ") / " . $nTotal . " = " . round($res, 3);
}
$solutionguide = arraytolist($guide_parts, "\n");

