// === NAME - DESCRIPTION: Sampling Distributions - Grading a Sum Interpretation ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Pair items with their appropriate units to avoid nonsense
$pairs = [
  ["packages", "pounds"],
  ["commutes", "minutes"],
  ["subscriptions", "dollars"],
  ["trips", "miles"]
];

// Pick one pair
$pairIdx = rand(0, 3);
$item = $pairs[$pairIdx][0];
$unit = $pairs[$pairIdx][1];

$mu = rand(10, 30);
$sigma = rand(2, 5);
$n = rand(20, 50);

$center = $n * $mu;
$spread = round(sqrt($n) * $sigma, 2);

// The Rubric
$rubric = "A complete response must: 1) State the expected sum is $center $unit. 2) State the standard deviation of the sum is $spread $unit. 3) Use appropriate phrasing such as 'on average' or 'expected'.";

// Define the four responses and their corresponding correct grade index
// Grade options: 0: Correct, 1: Wrong spread, 2: Wrong center, 3: Missing phrasing/context
$responses_data = [
  ["On average, the total for $n $item is expected to be $center $unit, with a standard deviation of $spread $unit.", 0],
  ["The sum of $n $item is expected to be $center $unit, and the standard deviation is $sigma $unit.", 1],
  ["The expected total for $n $item is $mu $unit with a standard deviation of $spread $unit.", 2],
  ["The sum is $center $unit and the standard deviation is $spread $unit.", 3]
];

// Shuffle the responses so the correct one isn't always first
// jointshuffle requires two arrays to shuffle them in tandem. 
// To shuffle a single array, we create a dummy array of the same size.
$shuffled_indices = listtoarray("0,1,2,3");
$dummy = listtoarray("0,0,0,0");
jointshuffle($shuffled_indices, $dummy);

$questions = [];
$answer = [];
$display_responses = [];

for ($i = 0; $i < 4; $i++) {
  $orig_idx = $shuffled_indices[$i];
  $display_responses[$i] = $responses_data[$orig_idx][0];
  $answer[$i] = $responses_data[$orig_idx][1];

  $questions[$i] = array(
    "Correct",
    "Incorrect: Wrong spread",
    "Incorrect: Wrong center",
    "Incorrect: Missing phrasing/context"
  );
}

$anstypes = "choices,choices,choices,choices";

$solutionguide = "The population mean is $mu and the standard deviation is $sigma. For a sample of size $n, the expected sum is $n * $mu = $center. The standard deviation of the sum is sqrt($n) * $sigma = $spread. The response that includes both these values and uses probabilistic phrasing like 'on average' or 'expected' is correct. The response using $sigma instead of $spread has the wrong spread. The response using $mu instead of $center has the wrong center. The response lacking 'expected' or 'on average' is missing phrasing.";

