// === COMMON CONTROL ===
// Randomly decide if the data is linear or non-linear
$is_linear = rand(0, 1);

$slope_gen = rand(1, 5);
$intercept_gen = rand(2, 10);
$noise_level = 3;

$x_vals = array();
$y_vals = array();
for ($i = 0; $i < 10; $i++) {
    $x = $i + 1;
    if ($is_linear) {
        // Linear trend with noise
        $noise = rand(-$noise_level, $noise_level);
        $y = ($slope_gen * $x) + $intercept_gen + $noise;
    } else {
        // Quadratic trend with noise
        $noise = rand(-$noise_level, $noise_level);
        $y = ($slope_gen * ($x**2)) + $intercept_gen + $noise;
    }
    $x_vals[] = $x;
    $y_vals[] = $y;
}

// Compute actual Least Squares Regression Line (LSRL)
$sumX = 0; $sumY = 0; $sumXY = 0; $sumX2 = 0;
$n = count($x_vals);
for ($i = 0; $i < $n; $i++) {
    $sumX += $x_vals[$i];
    $sumY += $y_vals[$i];
    $sumXY += ($x_vals[$i] * $y_vals[$i]);
    $sumX2 += ($x_vals[$i]**2);
}

$ls_slope = ($n * $sumXY - $sumX * $sumY) / ($n * $sumX2 - $sumX**2);
$ls_intercept = ($sumY - $ls_slope * $sumX) / $n;

// Create the scatterplot using SVG
$width = 400;
$height = 300;
$margin = 40;
$plot_w = $width - 2 * $margin;
$plot_h = $height - 2 * $margin;

// Scaling
$x_min = 0; $x_max = 11;
$y_min = min($y_vals) - 2; $y_max = max($y_vals) + 2;
$y_range = $y_max - $y_min;

$points_svg = "";
foreach ($x_vals as $idx => $xv) {
    $px = $margin + ($xv - $x_min) / ($x_max - $x_min) * $plot_w;
    $py = ($height - $margin) - ($y_vals[$idx] - $y_min) / $y_range * $plot_h;
    $points_svg .= "<circle cx='$px' cy='$py' r='3' fill='blue'/>";
}

// Draw the LSRL
$line_x1 = $margin + (1 - $x_min) / ($x_max - $x_min) * $plot_w;
$line_y1 = ($height - $margin) - (($ls_slope * 1 + $ls_intercept) - $y_min) / $y_range * $plot_h;
$line_x2 = $margin + (10 - $x_min) / ($x_max - $x_min) * $plot_w;
$line_y2 = ($height - $margin) - (($ls_slope * 10 + $ls_intercept) - $y_min) / $y_range * $plot_h;
$line_svg = "<line x1='$line_x1' y1='$line_y1' x2='$line_x2' y2='$line_y2' stroke='red' stroke-width='2'/>";

$graph = "<svg width='$width' height='$height' style='display:block; margin:auto;'>
