$denM = $x2 - $x1;
$m = $numM / $denM;

// Calculate y-intercept b = y1 - m*x1
$numB = $y1 * ($x2 - $x1) - $x1 * ($y2 - $y1);
$denB = $x2 - $x1;
$b = $numB / $denB;

// In IMathAS, for numfunc, the answer should be a string representing the algebraic expression.
// We build the string using concatenation to avoid PHP trying to multiply a number by the string 'x'.
$answer = "(" . $m . ")*x + (" . $b . ")";

