// The amplitude is the absolute value of the coefficient of the sine term.
$correct_val = $amp;

// Generate distractors that are guaranteed to be different from the correct answer and each other.
$distractors = [];
while (count($distractors) < 3) {
    $d = rand(1, 20);
    if ($d != $correct_val && !in_array($d, $distractors)) {
        $distractors[] = $d;
    }
}

// Create the options array
$options = [$correct_val, $distractors[0], $distractors[1], $distractors[2]];

// Create an index array [0, 1, 2, 3] using listtoarray to avoid range()
$shuffled_indices = listtoarray([0, 1, 2, 3]);

// jointshuffle requires two arrays to shuffle them in tandem. 
// To shuffle a single array, we create a dummy array of the same size.
$dummy = listtoarray([0, 0, 0, 0]);
jointshuffle($shuffled_indices, $dummy);

// Initialize $questions as an array to avoid "not defined" errors
$questions = [];
// Use the required foreach syntax: foreach ($arr as $key => $val)
foreach ($shuffled_indices as $k => $idx) {
    $questions[$k] = (string)$options[$idx];
}

// Find which index the correct value ended up at
$answer = -1;
for ($i = 0; $i < 4; $i++) {
    if ($options[$shuffled_indices[$i]] == $correct_val) {
        $answer = $i;
    }
}

